# Generated by test-lab — blind adversarial evaluation
"""Executable tests for ping_pong_state loaded via importlib."""
from __future__ import annotations

import importlib.util
import json
import tempfile
from pathlib import Path

import sys

ROOT = Path(__file__).resolve().parents[1]
MODULE_PATH = ROOT / "ping_pong_state.py"
spec = importlib.util.spec_from_file_location("ping_pong_state", MODULE_PATH)
assert spec is not None and spec.loader is not None
pps = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = pps
spec.loader.exec_module(pps)


def test_run_state_and_events() -> None:
    with tempfile.TemporaryDirectory() as td:
        run = pps.create_run(
            Path(td),
            run_id="run-1",
            idle_timeout_seconds=30,
            max_wall_clock_seconds=120,
            requested_model="requested-model",
            requested_reasoning="high",
            bundle_path="bundle.tar.gz",
            artifact_paths={"review": "review.md"},
        )
        run.append_event("run_started")
        run.append_event("reviewer_started", actual_model="actual-model", actual_reasoning="medium")
        run.append_event("reviewer_event", message="thinking")
        run.append_event("clarification_requested", question="Proceed?")
        run.append_command("parent_response", response="yes")
        run.append_event("parent_response", response="yes")
        run.append_command("course_correction", instruction="focus on durability")
        run.append_event("reviewer_completed")
        run.append_event("recommendation", summary="ship it")
        run.append_event("run_completed")

        state = pps.read_state(run.state_path)
        assert state.run_id == "run-1"
        assert state.status == "completed"
        assert state.rounds_completed == 1
        assert state.requested_model == "requested-model"
        assert state.actual_model == "actual-model"
        assert state.requested_reasoning == "high"
        assert state.actual_reasoning == "medium"
        assert state.bundle_path == "bundle.tar.gz"
        assert state.artifact_paths == {"review": "review.md"}
        assert state.last_event_at

        batch = run.events_since(0)
        assert [record["event"] for record in batch.records] == [
            "run_started",
            "reviewer_started",
            "reviewer_event",
            "clarification_requested",
            "parent_response",
            "reviewer_completed",
            "recommendation",
            "run_completed",
        ]
        assert batch.next_offset > 0

        commands = run.commands_since(0).records
        assert [record["command"] for record in commands] == ["parent_response", "course_correction"]

        lines = list(pps.sse_lines(batch.records[:1], id_start=7))
        assert lines[0] == "id: 7\n"
        assert lines[1] == "event: run_started\n"
        assert lines[2].startswith("data: {")


def test_partial_final_line_is_ignored_and_retried() -> None:
    with tempfile.TemporaryDirectory() as td:
        path = Path(td) / "events.jsonl"
        end = pps.append_jsonl(path, {"event": "run_started", "run_id": "run-2"}, fsync=False)
        with path.open("ab") as handle:
            partial_start = handle.tell()
            handle.write(b'{"event":"reviewer_started"')

        batch = pps.read_jsonl(path)
        assert len(batch.records) == 1
        assert batch.next_offset == partial_start
        assert end == partial_start

        with path.open("ab") as handle:
            handle.write(b',"run_id":"run-2"}\n')
        retry = pps.read_jsonl(path, start_offset=batch.next_offset)
        assert len(retry.records) == 1
        assert retry.records[0]["event"] == "reviewer_started"


def test_state_write_is_json() -> None:
    with tempfile.TemporaryDirectory() as td:
        path = Path(td) / "state.json"
        state = pps.RunState(run_id="run-3", artifact_paths={"events": "events.jsonl"})
        pps.write_state(path, state)
        data = json.loads(path.read_text())
        assert data["run_id"] == "run-3"
        assert data["artifact_paths"] == {"events": "events.jsonl"}


def main() -> None:
    test_run_state_and_events()
    test_partial_final_line_is_ignored_and_retried()
    test_state_write_is_json()
    print("ping_pong_state tests passed")


if __name__ == "__main__":
    main()
